    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        bool reverted;
        try c.transfer(from, caddress, _tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool shouldRevert = false;
        for (uint i = 0; i < _tos.length; i++) {
            (bool ok, bytes memory ret) = caddress.call(
                abi.encodeWithSignature("transferFrom(address,address,uint256)", from, _tos[i], v)
            );
            if (!ok) {
                shouldRevert = true;
                break;
            }
            if (ret.length > 0) {
                if (!abi.decode(ret, (bool))) {
                    shouldRevert = true;
                    break;
                }
            }
        }

        assert(reverted == shouldRevert);
    }

    receive() external payable {}
}

